//! MNIST test-image loader.
//!
//! Reads `bench/data/mnist_images.toml`, which is generated by
//! `bench/data/mnist_prep.py` from the standard MNIST IDX files.
//! Run the prep script once before benchmarking:
//!
//!   cd bench/data && python3 mnist_prep.py

use std::path::Path;
use serde::Deserialize;

pub struct MnistData {
    /// Encoded pixel arrays, one per digit class (index = class 0..9).
    /// Each inner Vec has 784 elements: `field_value = pixel_u8 * 64 / 255`.
    pub images: Vec<Vec<u64>>,
    /// Ground-truth digit label for each image (always [0, 1, …, 9]).
    pub labels: Vec<usize>,
}

#[derive(Deserialize)]
struct MnistToml {
    labels:         LabelsSection,
    pixels:         PixelsSection,
}

#[derive(Deserialize)]
struct LabelsSection {
    values: Vec<usize>,
}

#[derive(Deserialize)]
struct PixelsSection {
    values: Vec<u64>,
}

/// Load MNIST test images from `<data_dir>/mnist_images.toml`.
///
/// Panics with a helpful message if the file is missing — run
/// `python3 bench/data/mnist_prep.py` to generate it.
pub fn load(data_dir: &Path) -> MnistData {
    let toml_path = data_dir.join("mnist_images.toml");
    let text = std::fs::read_to_string(&toml_path).unwrap_or_else(|_| {
        panic!(
            "cannot read {}; run `python3 bench/data/mnist_prep.py` first",
            toml_path.display()
        )
    });
    let parsed: MnistToml = toml::from_str(&text)
        .unwrap_or_else(|e| panic!("TOML parse error in {}: {e}", toml_path.display()));

    let n = parsed.labels.values.len();
    assert_eq!(
        parsed.pixels.values.len(),
        n * 784,
        "expected {} pixel values ({}×784), got {}",
        n * 784,
        n,
        parsed.pixels.values.len()
    );

    let images: Vec<Vec<u64>> = parsed
        .pixels
        .values
        .chunks(784)
        .map(|c| c.to_vec())
        .collect();

    MnistData { images, labels: parsed.labels.values }
}
